    .FirstOrDefault(o => o.Entry == objectId && o.IsValid);

if (grave != null)
{
    // Взаимодействуем
    wManager.Wow.Helpers.Interact.InteractGameObject(grave.GetBaseAddress);

    await Coroutine.Sleep(500); // Подождать немного, чтобы открылось окно

    // Выполняем Lua-клики
    Lua.DoString("GossipTitleButton1:Click();");
    await Coroutine.Sleep(100);
    Lua.DoString("QuestFrameCompleteQuestButton:Click();");
}

