// Sample of how to use Zeppelin/Ship
// In this sample, catch Zeppelin from Kalimdor (Ogrimmard) to Northrend (Borean Tundra (Warsong Hold))

/* Quest settings:
    * Can condition: "return Usefuls.ContinentId == (int) ContinentId.Azeroth;"
    * Is complete condition: "return Usefuls.ContinentId == (int) ContinentId.Kalimdor && !Me.InTransport;"
    * Not required in quest log: "True"
    * Quest type: "OverridePulseCSharpCode"
*/

// You can get zeppelin/ship/player positions and entry ID in tab "Tools" > "Development Tools" > "Dump all informations" (or "Memory information").

// Settings:
var zeppelinEntryId = 20808; // Zeppelin/Ship EntryId
// From
var fromZeppelinWaitPosition = new WoWPoint(-14277.75, 582.8661, 0.01345738); // Position where Zeppelin/Ship waits players (from)
var fromPlayerWaitPosition = new WoWPoint(-14284.47f, 558.139f, 8.829907f); // Position where the player waits Zeppelin/Ship (from)
var fromPlayerInZeppelinPosition = new WoWPoint(-14271.18f, 588.5197f, 6.07734f); // Position where the player waits in the Zeppelin/Ship (from)
// To
var toZeppelinWaitPosition = new WoWPoint(-1005.613, -3841.648, 0.02679261); // Position where Zeppelin/Ship waits players (to)
var toPlayerLeavePosition = new WoWPoint(-994.6528f, -3825.609f, 5.631267f); // Position to go out the Zeppelin/Ship (to)

// Change settings:
wManager.wManagerSetting.CurrentSetting.CloseIfPlayerTeleported = false;

// Code:
if (!Conditions.InGameAndConnectedAndProductStartedNotInPause)
    return true;

if (Usefuls.ContinentId == (int)ContinentId.Azeroth)
{
    if (!Me.InTransport)
    {
        if (GoToTask.ToPosition(fromPlayerWaitPosition))
        {
            var zeppelin = ObjectManager.GetWoWGameObjectByEntry(zeppelinEntryId).OrderBy(o => o.GetDistance).FirstOrDefault();
            if (zeppelin != null && zeppelin.Position.DistanceTo(fromZeppelinWaitPosition) < 1)
            {
                GoToTask.ToPosition(fromPlayerInZeppelinPosition);
            }
        }
    }
}
else if (Usefuls.ContinentId == (int)ContinentId.Kalimdor)
{
    if (Me.InTransport)
    {
        var zeppelin = ObjectManager.GetWoWGameObjectByEntry(zeppelinEntryId).OrderBy(o => o.GetDistance).FirstOrDefault();
        if (zeppelin != null && zeppelin.Position.DistanceTo(toZeppelinWaitPosition) < 1)
        {
            GoToTask.ToPosition(toPlayerLeavePosition);
        }
    }
}
return true;

