Thread t = System.Threading.Tasks.Task.Run(async () =>
    {
     int itemId = 12284;
     int questId = 2681;
     while (TreeRoot.IsRunning)
     {
      if (Me.IsAlive && Me.IsAutoRunning)
      {
       if (!Quest.HasQuest(questId))
        break;
       if (Me.CurrentTarget.IsValid && Me.CurrentTarget.IsAlive && Me.CurrentTarget.HealthPercent <= 90)
       {
Me.ClearTarget();   
UseItem(itemId);
await Coroutine.Sleep(5000);
     wManager.wManagerSetting.CurrentSetting.ListHarvest.Add(175264);   
       }
      }
      await Coroutine.Sleep(5000);
     }
    });
    

