If.CustomBehavior:
Thread t = System.Threading.Tasks.Task.Run(async () =>
{
 int item1 = 12886;
 int item2 = 12887;
 int itemToUse = 12888;
 int questId = 5149;

 while (TreeRoot.IsRunning)
 {
  if (wManager.Wow.Helpers.Me.IsAlive && Me.IsAutoRunning)
  {
   if (!Quest.HasQuest(questId))
    break;

   int count1 = GetItemCountById(item1);
   int count2 = GetItemCountById(item2);
   int count3 = GetItemCountById(itemToUse);

   if (count1 > 0 && count2 > 0 && count3 > 0)
   {
    UseItem(itemToUse);
    wManager.Wow.Helpers.Usefuls.WaitIsCasting();
    break;
   }
  }
  await Coroutine.Sleep(1000);
 }
});

