If.CustomBehavior:
Thread t = System.Threading.Tasks.Task.Run(async () =>
{
 int questId = 5211;
 int npcId = 11064;

 while (TreeRoot.IsRunning)
 {
  if (wManager.Wow.Helpers.Me.IsAlive && Me.IsAutoRunning)
  {
   if (!Quest.HasQuest(questId))
    break;

   var npc = wManager.Wow.ObjectManager.ObjectManager.GetObjectWoWUnit()
       .Find(u => u.Entry == npcId && u.IsAlive && u.GetDistance <= 5);

   if (npc != null)
   {
    wManager.Wow.Helpers.Interact.InteractGameObject(npc.GetBaseAddress);
    await Coroutine.Sleep(2000);
   }
  }
  await Coroutine.Sleep(1000);
 }
});

